### Step 3: Implement the database interactions

Use SQLite to store and retrieve data.

#### `src/db.js`
```javascript
// src/db.js
const sqlite3 = require('sqlite3');
const fs = require('fs');

const db = new sqlite3.Database('team_notes.db');

db.run(`
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY,
  email TEXT UNIQUE,
  password TEXT,
  salt TEXT,
  created_at INTEGER,
  updated_at INTEGER
);
`);

db.run(`
CREATE TABLE IF NOT EXISTS notes (
  id INTEGER PRIMARY KEY,
  title TEXT,
  body TEXT,
  created_at INTEGER,
  updated_at INTEGER,
  user_id INTEGER
);
`);

db.run(`
CREATE UNIQUE INDEX idx_users_email ON users(email);
CREATE UNIQUE INDEX idx_notes_title ON notes(title);
CREATE UNIQUE INDEX idx_notes_body ON notes(body);
CREATE UNIQUE INDEX idx_notes_user_id ON notes(user_id);
`);

module.exports = db;
```

